/**
 * No REST base URL resolved for a Bitbucket call: no `apiBaseUrl`, no
 * `BITBUCKET_API_BASE_URL`, and no Cursor SCM proxy. A Data Center channel
 * that only receives webhooks is in this state, so outbound defaults skip
 * the call instead of failing the turn. Not part of the public API.
 */
export class BitbucketApiBaseMissingError extends Error {
    constructor() {
        super("bitbucketChannel: no Bitbucket API base URL (pass apiBaseUrl, set BITBUCKET_API_BASE_URL, or serve with --cursor-scm-proxy and cursorAccount).");
        this.name = "BitbucketApiBaseMissingError";
    }
}
